// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // NETM is onlyOwner; the deployer (this test contract) is the owner.
        // Restrict any fuzzed actor so the test only exercises admissible inputs.
        vm.assume(actor != address(0));

        // Drive c through NETM from the legitimate owner (msg.sender at deploy).
        vm.prank(address(this));
        c.NETM();

        // General rule: after NETM(), the owner's credited balance equals
        // the contract's reported totalDistributed, never totalRemaining.
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // deployer (this contract) is owner; hand ownership to the fuzzed actor
        c.transferOwnership(actor);

        // actor (now owner) drives the entry point under test
        vm.prank(actor);
        c.NETM();

        // General rule: owner's credited balance + undistributed remainder == totalSupply
        assertTrue(c.balanceOf(actor) + c.totalRemaining() == c.totalSupply());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address key) public {
        vm.assume(actor != address(this)); // owner is the deployer (this test contract)
        vm.assume(actor != address(c));
        vm.prank(actor);
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }
        // General rule: a non-owner cannot redistribute; all balances stay zero.
        assertTrue(c.balances(key) == 0);
    }
}
